(()=>{
 const h=window.hb5,{tr,esc,title,note,table,select,button}=h;
 h.views.erp=()=>title('07 / ERP HANDOFF',tr('ERP connection and document mapping','ERP 연결·문서 매핑'),tr('ERP not selected. Keep the billing model independent of the destination system.','ERP 미선택. 빌링 데이터는 대상 ERP와 분리된 공통 규격으로 관리합니다.'))+`<form class="action-form">${select('erpScope',tr('Destination owner','연동 대상'),[['msp',tr('MSP internal ERP','MSP 내부 ERP')],['customer',tr('Customer ERP · separate authorization','고객사 ERP · 별도 승인')]],'msp')}${select('erpPurpose',tr('Purpose','처리 목적'),[['invoice',tr('Invoice / receivable handoff','인보이스·채권 인계')],['cost',tr('Monthly cost recognition','월별 비용 인식')]],'invoice')}${select('erpConnector',tr('Connector candidate','연결 후보'),[['none',tr('Not selected','미선택')],['odoo',tr('Odoo · version / hosting unverified','Odoo · 버전·운영 형태 미확인')],['file',tr('Validated file handoff','검증된 파일 인계')]],'none')}${button('erpCheck',tr('Check preparation gaps · demo','준비 항목 확인 · 시연'))}</form>`+table([tr('Layer','구분'),tr('Common contract','공통 계약'),tr('Evidence required','필요 근거')],[[tr('Destination','대상'),tr('Legal entity / ledger / company ID','법인 / 장부 / 회사 ID'),tr('Exact destination and authorized finance owner','실제 대상과 권한 있는 회계 담당자')],[tr('Billing document','청구 문서'),tr('Period, currency, lines, discounts, tax, total, original reference','기간·통화·항목·할인·세금·총액·원본 참조'),tr('UBL / Peppol profile candidate; not yet certified','UBL / Peppol 프로파일 후보 · 준수 검증 전')],[tr('Accounting recognition','회계 인식'),tr('Recognition period, purpose, amount basis, approved mappings','인식 기간·목적·금액 기준·승인된 매핑'),tr('ERP-specific account/tax mapping and duplicate-recognition prevention','ERP별 계정·세금 매핑 및 이중 인식 방지')],[tr('Submission','제출'),tr('Stable submission ID, revision, retry/reconciliation state','고정 제출 ID·개정·재시도·대사 상태'),tr('Verified API or file import profile; no direct DB writes','검증된 API·파일 가져오기 프로파일 · DB 직접 쓰기 금지')],[tr('Result','결과'),tr('Received / posted / failed / outcome unknown','접수 / 전기 완료 / 실패 / 결과 불명'),tr('External document ID and confirmation time; sending is not posting','외부 전표 ID·확인 시각 · 전송과 전기 완료 구분')]])+`<h2>${tr('Connection readiness','연결 준비 상태')}</h2>`+table([tr('Step','단계'),tr('Current status','현재 상태')],[[tr('1. Select ERP / version / hosting','1. ERP·버전·운영 형태 선택'),tr('Not selected','미선택')],[tr('2. Set legal entity, ledger and purpose','2. 법인·장부·처리 목적 설정'),tr('Not configured','미설정')],[tr('3. Approve mappings and validate capabilities','3. 매핑 승인·지원 기능 검증'),tr('Not verified','미검증')],[tr('4. Enable submission after acceptance','4. 인수 검증 후 제출 활성화'),tr('Disabled','비활성')]])+note(tr('No credentials, ERP calls, file submission or posting are connected. Odoo is a candidate, not a selected dependency. Invoice standards do not define universal ledger posting; cost recognition stays separate from customer billing.','인증 정보·ERP 호출·파일 제출·전기는 연결되지 않았습니다. Odoo는 후보이며 확정 의존성이 아닙니다. 인보이스 표준은 범용 회계 전기를 정의하지 않으며 비용 인식과 고객 청구는 분리합니다.'));
 document.addEventListener('click',e=>{
  if(e.target.closest('[data-action]')?.dataset.action!=='erpCheck')return;
  const value=n=>document.querySelector(`[name="${n}"]`).value;
  const selected=value('erpConnector'),scope=value('erpScope'),purpose=value('erpPurpose');
  document.querySelector('#feedback').textContent=tr('NOT READY — ','준비 미완료 — ')+(selected==='none'?tr('Choose a connector. ','연결 후보를 선택하세요. '):selected==='odoo'?tr('Odoo version, hosting and API availability need validation. ','Odoo 버전·운영 형태·API 제공 여부 확인 필요. '):tr('Destination file schema and import-result evidence required. ','대상 파일 규격·가져오기 결과 근거 필요. '))+(scope==='customer'?tr('Customer legal entity and separate access approval required. ','고객 법인·별도 접근 승인 필요. '):tr('MSP legal entity and ledger required. ','MSP 법인·장부 설정 필요. '))+(purpose==='cost'?tr('Cost-recognition mapping and duplicate-recognition checks required. No submission occurred.','비용 인식 매핑·이중 인식 검증 필요. 제출하지 않았습니다.'):tr('Invoice mapping and external result checks required. No submission occurred.','인보이스 매핑·외부 결과 검증 필요. 제출하지 않았습니다.'));
 });
})();
